/*
 * EFFB8_MES_PT.C  Win messages, Portuguese
 *
 * The arrays of message records effB8_mes_pt points at, one per player, and the lists the records
 * name. Effect B8 picks a player's array from effB8_mes_pt; a record names a conn list (the panel's
 * cells: x, y, colour, character) and a chr list (the number of characters to load, the characters,
 * the number of cells). An array is named after the first entry of effB8_mes_pt (player number)
 * that points at it, its lists after the array and the index of their pointer in it (record j: conn
 * 2j, chr 2j + 1).
 */

